import sys


def for_range(a, b):
    if a < b:
        return range(a, b + 1)
    return range(a, b - 1, -1)


def arr(a, b, fn=None, prev=None):
    values = for_range(a, b)
    if fn is None:
        return list(values)

    p = prev or 0
    result = []
    for i in values:
        p = fn(i, p)
        result.append(p)
    return result


def gcd(a, b):
    if not b:
        return a
    return gcd(b, a % b)


def mod(a, n, m):
    if n == 0:
        return 1
    if n % 2 == 0:
        return mod(a * a % m, n // 2, m)
    return a * mod(a, n - 1, m) % m


def extended_euclid(a, b):
    if not b:
        return 1, 0
    x, y = extended_euclid(b, a % b)
    return y, x - int(a / b) * y


def main():
    inp = sys.stdin.buffer.read().split()
    n = int(inp[0])
    k = int(inp[1])
    s = inp[2].decode()
    t = inp[3].decode()

    if t[0] == t[1]:
        x = min(s.count(t[0]) + k, n)
        print(x * (x - 1) // 2)
        return

    f = [[[-100000 for _ in range(n + 2)]
          for _ in range(n + 2)]
         for _ in range(n + 2)]
    f[0][0][0] = 0

    for i in range(n + 1):
        for j in range(k + 1):
            for cnt0 in range(i + 1):
                if f[i][j][cnt0] < 0:
                    continue

                e0 = int(i < n and s[i] == t[0])
                e1 = int(i < n and s[i] == t[1])

                f[i + 1][j][cnt0 + e0] = max(
                    f[i + 1][j][cnt0 + e0],
                    f[i][j][cnt0] + e1 * cnt0
                )
                f[i + 1][j + 1][cnt0 + 1] = max(
                    f[i + 1][j + 1][cnt0 + 1],
                    f[i][j][cnt0]
                )
                f[i + 1][j + 1][cnt0] = max(
                    f[i + 1][j][cnt0],
                    f[i][j][cnt0] + cnt0
                )

    print(max(f[n][i][j] for i in range(k + 1) for j in range(n + 1)))


if __name__ == "__main__":
    main()

